from .cycle import CircularDependencyError

class DependencyResolver:
    def __init__(self, deps: dict[str, list[str]]):
        self.deps = deps

    def resolve(self) -> list[str]:
        # In-degree computation for Kahn's algorithm
        nodes = set(self.deps.keys())
        for targets in self.deps.values(): nodes.update(targets)
        in_degree = {n: 0 for n in nodes}
        for targets in self.deps.values():
            for t in targets: in_degree[t] += 1
        queue = sorted([n for n, deg in in_degree.items() if deg == 0])
        res = []
        while queue:
            curr = queue.pop(0)
            res.append(curr)
            for nxt in sorted(self.deps.get(curr, [])):
                in_degree[nxt] -= 1
                if in_degree[nxt] == 0: queue.append(nxt)
        if len(res) < len(nodes):
            raise CircularDependencyError('Cycle detected')
        return res

