import unittest
from dag.resolver import DependencyResolver, CircularDependencyError

class TestDAG(unittest.TestCase):
    def test_dag_ordering(self):
        deps = {'a': ['b'], 'b': ['c'], 'c': []}
        r = DependencyResolver(deps).resolve()
        self.assertEqual(r, ['a', 'b', 'c'])

    def test_cycle_trace(self):
        deps = {'a': ['b'], 'b': ['c'], 'c': ['a']}
        with self.assertRaises(CircularDependencyError) as ctx:
            DependencyResolver(deps).resolve()
        self.assertTrue(hasattr(ctx.exception, 'cycle'))
        self.assertTrue(len(ctx.exception.cycle) >= 3)

if __name__ == '__main__': unittest.main()
